    // 3. New Bin Dynamics: Calibrate the "New Bin" cost.
    if bin_residual == bin_capacity {
        // Dynamic thresholding: if mean_residual is low, we have capacity, so penalize opening a new bin harder.
        let density_factor = (open_bins_count as f64).min(32.0) * 4.2;
        score += 82.0 + (mean_residual * 0.42) - density_factor;
    } else {
        // 4. Harmonic Alignment: Shift to 16-unit alignment for better fit with standard item sizes.
        let remainder = post_residual % 16;
        score += (remainder as f64) * 0.72;

        // 5. Aggressive Closure: If a bin is near completion, force it to finish.
        if post_residual < 10 {
            score -= 36.0;
        }
    }

    // 6. Terminal Compaction: Exponentially scale pressure to fill gaps in the final 20% of stream.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.80 {
        score += (post_residual as f64) * (2.2 + (progress - 0.80) * 25.0);
    } else {
        score += (post_residual as f64) * 0.22;
    }

    // 7. Global Load Balancing: Avoid creating fragmented bins if we have sufficient fitting options.
    if open_bins_count > 8 && post_residual < 18 {
        score += 24.0;
    }

    // 8. Scarcity Adjustment: If few bins can fit, prioritize the ones that can to prevent premature new bin opening.
    if fitting_bins_count < 4 {
        score -= 28.0;
    }

    // 9. Residual Variance Dampening: Penalize bins that deviate significantly from the mean_residual.
    let variance_penalty = ((post_residual as f64) - mean_residual).abs() * 0.15;
    score += variance_penalty;

    score
}
